const state = { file: null, lyricsFile: null, playing: false, progress: 37, timer: null, settings: { avatar: '女性角色', purpose: '专业创作', style: '舞蹈审美' } };
const $ = (selector, root = document) => root.querySelector(selector);
const $$ = (selector, root = document) => [...root.querySelectorAll(selector)];
const toast = (message) => { const el = $('.toast'); if (!el) return; el.textContent = message; el.classList.add('show'); clearTimeout(window.__toast); window.__toast = setTimeout(() => el.classList.remove('show'), 2400); };
function showView(name) { $$('.view').forEach(view => view.classList.toggle('active', view.dataset.view === name)); $$('.nav button').forEach(button => button.classList.toggle('active', button.dataset.target === name)); window.scrollTo({ top: 0, behavior: 'smooth' }); }
function unlock(name) { const button = $(`.nav button[data-target="${name}"]`); if (button) button.disabled = false; }
function setFile(file) { if (!file) return; if (file.type && !file.type.startsWith('audio/')) { toast('请选择 MP3、WAV 或 M4A 音频'); return; } state.file = file; $('.file-ready')?.classList.add('visible'); if ($('.file-name')) $('.file-name').textContent = file.name; if ($('.file-size')) $('.file-size').textContent = `${(file.size / 1024 / 1024).toFixed(1)} MB · 已准备分析`; toast('音乐已载入，可以开始分析'); }
function simulateUpload() { state.file = { name: 'Midnight Bloom.mp3', size: 4.2 * 1024 * 1024, type: 'audio/mpeg' }; $('.file-ready')?.classList.add('visible'); $('.file-name').textContent = state.file.name; $('.file-size').textContent = '4.2 MB · 示例音乐已准备'; toast('示例音乐已载入'); }
function setLyricsFile(file) { if (!file) return; if (!/\.(lrc|txt)$/i.test(file.name)) { toast('请选择 LRC 或 TXT 歌词文件'); return; } state.lyricsFile = file; if ($('.lyrics-file-name')) $('.lyrics-file-name').textContent = `${file.name} · 已载入`; toast('歌词已载入'); }
function runAnalysis() { if (!state.file) { toast('请先上传音乐，或点击“模拟上传”'); return; } showView('report'); unlock('report'); unlock('settings'); unlock('player'); toast('分析完成：音乐画像已生成'); }
function startGeneration() { const overlay = $('.progress-overlay'); const progress = $('.progress-track i'); const label = $('.progress-step'); if (!overlay) return; overlay.classList.add('show'); let index = 0; const steps = ['准备动作骨架…', '匹配节拍与段落…', '套用角色和风格…', '生成播放舞台…', '编舞已准备完成']; const tick = () => { const value = (index + 1) * 20; if (progress) progress.style.width = `${value}%`; if (label) label.textContent = steps[index]; if (index < steps.length - 1) { index += 1; setTimeout(tick, 450); } else setTimeout(() => { overlay.classList.remove('show'); showView('player'); toast('编舞已生成，开始预览吧'); }, 550); }; tick(); }
function updateSummary() { const text = `${state.settings.avatar} · ${state.settings.purpose} · ${state.settings.style}`; if ($('.setting-summary')) $('.setting-summary').textContent = text; if ($('.summary-avatar')) $('.summary-avatar').textContent = state.settings.avatar; if ($('.summary-purpose')) $('.summary-purpose').textContent = state.settings.purpose; if ($('.summary-style')) $('.summary-style').textContent = state.settings.style; }
function togglePlayback() { state.playing = !state.playing; const play = $('.play'); const live = $('.live'); const dancer = $('.stage-player .dancer'); if (play) play.textContent = state.playing ? 'Ⅱ' : '▶'; if (live) live.textContent = state.playing ? '● PLAYING / SYNCED' : '● READY / PAUSED'; if (dancer) dancer.style.animationPlayState = state.playing ? 'running' : 'paused'; clearInterval(state.timer); if (state.playing) state.timer = setInterval(() => { state.progress = state.progress >= 99 ? 0 : state.progress + .35; const bar = $('.transport-bar i'); if (bar) bar.style.width = `${state.progress}%`; const time = $('.current-time'); if (time) time.textContent = `0${Math.floor(state.progress / 10)}:${String(Math.floor((state.progress % 10) * 6)).padStart(2, '0')}`; }, 100); }
function bind() { $$('.nav button:not(:disabled), .brand').forEach(button => button.addEventListener('click', event => { event.preventDefault(); const target = button.dataset.target || 'home'; showView(target); })); $('#file-input')?.addEventListener('change', event => setFile(event.target.files[0])); $('#lrc-input')?.addEventListener('change', event => setLyricsFile(event.target.files[0])); $('.demo-upload')?.addEventListener('click', simulateUpload); $('.start-analysis')?.addEventListener('click', runAnalysis); $('.next-settings')?.addEventListener('click', () => showView('settings')); $('.confirm-settings')?.addEventListener('click', startGeneration); $('.dropzone')?.addEventListener('dragover', event => { event.preventDefault(); $('.dropzone').classList.add('dragging'); }); $('.dropzone')?.addEventListener('dragleave', () => $('.dropzone').classList.remove('dragging')); $('.dropzone')?.addEventListener('drop', event => { event.preventDefault(); $('.dropzone').classList.remove('dragging'); setFile(event.dataTransfer.files[0]); }); $('.play')?.addEventListener('click', togglePlayback); $('.restart')?.addEventListener('click', () => { state.progress = 0; const bar = $('.transport-bar i'); if (bar) bar.style.width = '0%'; toast('已回到开头'); }); $('.transport-bar')?.addEventListener('click', event => { const rect = event.currentTarget.getBoundingClientRect(); state.progress = ((event.clientX - rect.left) / rect.width) * 100; event.currentTarget.querySelector('i').style.width = `${state.progress}%`; }); $$('.segment').forEach(button => button.addEventListener('click', () => { $$('.segment').forEach(item => item.classList.remove('active')); button.classList.add('active'); if ($('.current-section')) $('.current-section').textContent = `${button.dataset.section} · 4 BARS`; })); $$('.version-btn').forEach(button => button.addEventListener('click', () => { $$('.version-btn').forEach(item => item.classList.remove('active')); button.classList.add('active'); if ($('.action-title')) $('.action-title').textContent = button.dataset.name; toast(`${button.dataset.name} 已载入`); })); $$('.choice-card,.choice-row').forEach(button => button.addEventListener('click', () => { const group = button.dataset.setting; $$(`[data-setting="${group}"]`).forEach(item => item.classList.remove('active')); button.classList.add('active'); state.settings[group] = button.dataset.value; updateSummary(); })); updateSummary(); }
bind();
